// 生成 6 位短信验证码
func GenOtpCode(phone string) string {
	seed := 0
	for _, c := range phone {
		seed += int(c)
	}
	r := rand.New(rand.NewSource(int64(seed)))
	return fmt.Sprintf("%06d", r.Intn(1000000))
